            throw new CheckoutException("MODALIDADE_INVALIDA");
        }

        String modalidade = request.getModalidadeEntrega().trim().toUpperCase();
        if (!isModalidadeValida(modalidade)) {
            throw new CheckoutException("MODALIDADE_INVALIDA");
